#!/usr/bin/env bash
# =============================================================================
# AlphaCP — D14 PARITY GAPS v1.0  (live panel 0.75.x + paneld · 09 Oct 2026)
#
# Phase-2 Wave D14: parity gaps — "ek bhi nahi chutna chahiye".
#   MAIL:  mailbox Suspend/Unsuspend (cPanel-style login suspend, data safe)
#   DNS:   AAAA record type + MX priority ("10 mail.example.com")
#   DB:    Revoke User From Database (grant ka ulta)
#   FIX:   email.update + zone-editor.update routes WAPAS (D7 me gir gaye the —
#          Email Accounts / Zone Editor pages 500 de rahe the)
# 12 files, multi-root. DB me KOI change nahi.
# Safety: backup (.bak-d14parity-<stamp>) -> install -> caches -> paneld gate ->
#   health -> AUTO-ROLLBACK.
# =============================================================================
set -Eeuo pipefail

D14_VERSION="1.0"
PANEL_ROOT="${PANEL_ROOT:-/usr/local/alphacp/panel}"
AGENT_ROOT="${AGENT_ROOT:-/usr/local/alphacp/agent}"
STAMP="$(date -u +%Y%m%d%H%M%S)"
LOG_FILE="/var/log/alphacp-d14-parity-gaps.log"

C_B=$'\033[1m'; C_G=$'\033[32m'; C_R=$'\033[31m'; C_Y=$'\033[33m'; C_0=$'\033[0m'
say() { printf '%s\n' "$*"; }
log() { printf '%s [%s]\n' "$(date -u '+%F %T')Z" "$*" >>"${LOG_FILE}" 2>/dev/null || true; }
ok()  { log "OK   $*"; say "${C_G}[OK]${C_0} $*"; }
warn(){ log "WARN $*"; say "${C_Y}[!]${C_0} $*"; }
die() { log "FAIL $*"; say "${C_R}[x]${C_0} $*"; say "Log: ${LOG_FILE}"; exit 1; }

say ""
say "${C_B}== AlphaCP D14 PARITY GAPS v${D14_VERSION} ==${C_0}"
[[ "${EUID}" -eq 0 ]] || die "root chahiye: sudo bash $0"
[[ -d "${PANEL_ROOT}/public/assets" ]] || die "panel nahi mila: ${PANEL_ROOT}"
[[ -f "${PANEL_ROOT}/public/assets/panel.js" ]] || die "pehle theme-fix v1.2 install karo (panel.js missing) — COMMANDS.md dekho"
[[ -f "${AGENT_ROOT}/config/tasks.php" ]] || die "agent nahi mila: ${AGENT_ROOT}"
grep -q "node.setup" "${AGENT_ROOT}/config/tasks.php" || die "agent tasks.php me D13 (node.setup) nahi — pehle D13 wave install karo"

